<script>export let data;</script><section class="page"><div class="eyebrow">ADOPTION</div><h1>Meet your possible new friend.</h1><p class="sub">Community adoption listings. Contact the person who posted a listing to learn more.</p><div class="toolbar"><form><input name="q" value={data.filters.q} placeholder="Search by area or details..."/><select name="animal"><option value="all">All animals</option><option value="dog" selected={data.filters.animal==='dog'}>Dogs</option><option value="cat" selected={data.filters.animal==='cat'}>Cats</option></select><button class="btn primary">Search</button></form><a class="btn light" href="/adoption/new">+ List an animal</a></div>{#if data.listings.length}<div class="masonry">{#each data.listings as item}<a class="card" href={`/report/${item.id}?kind=adoption`}><div>{#if item.image_url}<img src={item.image_url} alt={item.title}/>{:else}<div class="image-placeholder">{item.animal_type==='cat'?'🐱':'🐶'}</div>{/if}</div><div class="card-body"><div class="meta"><span>{item.animal_type}</span><span>available</span></div><h3>{item.title}</h3><p>{item.description}</p><small>📍 {item.location}</small></div></a>{/each}</div>{:else}<div class="empty">No adoption listings found.</div>{/if}</section>
